+std::optional<bool> WebRtcVoiceSendChannel::muted() const {
+  RTC_DCHECK_RUN_ON(worker_thread_);
+  std::optional<bool> muted;
+  for (const auto& [ssrc, stream] : send_streams_) {
+    if (stream->muted() == false) {
