+// Calls OnClose() on its sink, as a source does when it goes away.
+class ClosableAudioSource : public AudioSource {
+ public:
+  void SetSink(Sink* sink) override { sink_ = sink; }
+  void Close() {
+    Sink* sink = sink_;
+    sink_ = nullptr;
+    if (sink) {
+      sink->OnClose();
+    }
+  }
+
+ private:
+  Sink* sink_ = nullptr;
+};
